// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }
    function testFuzz_property(address logger) public {
        // The contract's owner is the zero address (default for the private _contractOwner).
        vm.prank(address(0));
        c.setApprovedLogger(logger, true);
        vm.prank(address(0));
        c.setApprovedLogger(logger, false);
        // General rule: after applying statuses true then false, the stored status equals false.
        assertTrue(c.approvedLoggers(logger) == false, "last status must win");
    }
}
